/**
 * Character stage — Abrar Alli Khan
 * Premium orbit studio using reference portraits (not a mesh scan).
 */
import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";

const SHIRT = "data:image/jpeg;base64,";
const FOUNDER = "data:image/jpeg;base64,";

export async function mountCharacterStage(canvas) {
  const parent = canvas.parentElement;
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  renderer.setClearColor(0x000000, 0);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.08;

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 40);
  camera.position.set(0.2, 0.08, 4.4);

  const controls = new OrbitControls(camera, canvas);
  controls.enableDamping = true;
  controls.dampingFactor = 0.06;
  controls.enablePan = false;
  controls.minDistance = 2.6;
  controls.maxDistance = 6.8;
  controls.target.set(0, 0.08, 0);
  controls.autoRotate = true;
  controls.autoRotateSpeed = 0.5;
  controls.maxPolarAngle = Math.PI * 0.62;
  controls.minPolarAngle = Math.PI * 0.34;

  scene.add(new THREE.AmbientLight(0xffffff, 0.9));
  const key = new THREE.DirectionalLight(0xffffff, 1.35);
  key.position.set(2.2, 3.2, 4);
  scene.add(key);
  const fill = new THREE.DirectionalLight(0xe8e0d8, 0.55);
  fill.position.set(-3, 1.2, -1.5);
  scene.add(fill);

  const ground = new THREE.Mesh(
    new THREE.CircleGeometry(1.55, 64),
    new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.4 })
  );
  ground.rotation.x = -Math.PI / 2;
  ground.position.y = -1.32;
  scene.add(ground);

  const ring = new THREE.Mesh(
    new THREE.RingGeometry(1.12, 1.145, 80),
    new THREE.MeshBasicMaterial({ color: 0x111111, transparent: true, opacity: 0.14, side: THREE.DoubleSide })
  );
  ring.rotation.x = -Math.PI / 2;
  ring.position.y = -1.31;
  scene.add(ring);

  const group = new THREE.Group();
  scene.add(group);

  const loader = new THREE.TextureLoader();
  const loadTex = (url) =>
    new Promise((resolve, reject) => {
      loader.load(url, (t) => {
        t.colorSpace = THREE.SRGBColorSpace;
        resolve(t);
      }, undefined, reject);
    });

  const [tShirt, tFounder] = await Promise.all([loadTex(SHIRT), loadTex(FOUNDER)]);

  const front = new THREE.Mesh(
    new THREE.PlaneGeometry(1.88, 2.38),
    new THREE.MeshStandardMaterial({ map: tShirt, roughness: 0.72, metalness: 0.02, transparent: true })
  );
  front.position.set(0, 0.08, 0.06);
  group.add(front);

  const depth = new THREE.Mesh(
    new THREE.PlaneGeometry(1.72, 2.18),
    new THREE.MeshStandardMaterial({
      map: tFounder,
      roughness: 0.8,
      metalness: 0.02,
      transparent: true,
      opacity: 0.18,
    })
  );
  depth.position.set(0.14, 0.04, -0.32);
  depth.rotation.y = 0.1;
  group.add(depth);

  const glass = new THREE.Mesh(
    new THREE.PlaneGeometry(2.02, 2.52),
    new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.28 })
  );
  glass.position.set(0, 0.08, -0.04);
  group.add(glass);

  function resize() {
    const w = parent.clientWidth;
    const h = parent.clientHeight;
    renderer.setSize(w, h, false);
    camera.aspect = w / Math.max(h, 1);
    camera.updateProjectionMatrix();
  }
  resize();
  const ro = new ResizeObserver(resize);
  ro.observe(parent);

  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reduce) controls.autoRotate = false;

  let raf = 0;
  function tick(t) {
    raf = requestAnimationFrame(tick);
    if (!reduce) group.position.y = Math.sin(t * 0.001) * 0.028;
    controls.update();
    renderer.render(scene, camera);
  }
  raf = requestAnimationFrame(tick);

  canvas.addEventListener("pointerdown", () => { controls.autoRotate = false; });
  canvas.addEventListener("pointerup", () => {
    if (!reduce) setTimeout(() => { controls.autoRotate = true; }, 2000);
  });

  return () => {
    cancelAnimationFrame(raf);
    ro.disconnect();
    controls.dispose();
    renderer.dispose();
  };
}
